// Camera catalog: types, parsing and lookup for the bundled AstroSubCalc
// camera database (public/catalogs/cameras.json, generated by
// scripts/generate-camera-catalog.mjs). Pure — no React, no Tauri, no DOM.

export interface CameraMode {
  id: string
  label: string
  gain: number
  readNoise: number
  fullWell: number
}

export interface Camera {
  id: string
  model: string
  vendor: string
  sensor: string
  mono: boolean
  pixelSize: number
  qe: number
  bitDepth: number
  resolutionX: number
  resolutionY: number
  maxCooling: number | null
  darkRef: number
  darkRefTemp: number
  darkDoubling: number
  modes: CameraMode[]
}

function isFiniteNumber(v: unknown): v is number {
  return typeof v === 'number' && Number.isFinite(v)
}

function assertCamera(c: unknown, index: number): asserts c is Camera {
  if (!c || typeof c !== 'object') throw new Error(`camera[${index}] is not an object`)
  const cam = c as Record<string, unknown>
  for (const key of ['id', 'model', 'vendor', 'sensor']) {
    if (typeof cam[key] !== 'string' || (cam[key] as string).trim() === '') {
      throw new Error(`camera[${index}].${key} must be a non-empty string`)
    }
  }
  if (typeof cam.mono !== 'boolean') throw new Error(`camera[${index}].mono must be a boolean`)
  for (const key of ['pixelSize', 'qe', 'bitDepth', 'resolutionX', 'resolutionY', 'darkRef', 'darkRefTemp', 'darkDoubling']) {
    if (!isFiniteNumber(cam[key])) throw new Error(`camera[${index}].${key} must be a finite number`)
  }
  if (cam.maxCooling !== null && !isFiniteNumber(cam.maxCooling)) {
    throw new Error(`camera[${index}].maxCooling must be a number or null`)
  }
  if (!Array.isArray(cam.modes) || cam.modes.length === 0) {
    throw new Error(`camera[${index}].modes must be a non-empty array`)
  }
  for (const [i, m] of (cam.modes as unknown[]).entries()) {
    const mode = m as Record<string, unknown>
    if (!mode || typeof mode !== 'object') throw new Error(`camera[${index}].modes[${i}] is not an object`)
    if (typeof mode.id !== 'string' || mode.id.trim() === '') throw new Error(`camera[${index}].modes[${i}].id must be a non-empty string`)
    if (typeof mode.label !== 'string') throw new Error(`camera[${index}].modes[${i}].label must be a string`)
    for (const key of ['gain', 'readNoise', 'fullWell']) {
      if (!isFiniteNumber(mode[key])) throw new Error(`camera[${index}].modes[${i}].${key} must be a finite number`)
    }
  }
}

export function parseCatalog(json: unknown): Camera[] {
  if (!json || typeof json !== 'object' || !Array.isArray((json as Record<string, unknown>).cameras)) {
    throw new Error('camera catalog must be an object with a "cameras" array')
  }
  const cameras = (json as { cameras: unknown[] }).cameras
  cameras.forEach((c, i) => assertCamera(c, i))
  return cameras as Camera[]
}

/** Lowercase alphanumerics only, for tolerant matching. */
function normalize(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, '')
}

/** Matches a FITS `INSTRUME` value to a catalog camera. Tries the header
 *  value against each model with and without its leading vendor word; the
 *  longest model key contained in the header key wins, so "…MM Pro" never
 *  matches "…MC Pro" and a longer model name beats a shorter one it contains. */
export function matchInstrume(cameras: Camera[], instrume: string): Camera | null {
  const header = normalize(instrume)
  if (!header) return null

  let best: Camera | null = null
  let bestLen = 0
  for (const camera of cameras) {
    const full = normalize(camera.model)
    // Only strip the vendor when it is a separate word (a trailing space):
    // a glued name like "QHY600M" must not strip down to a bare, generic
    // "600m" that then false-matches as a substring of an unrelated header.
    const withoutVendor = normalize(camera.model.replace(new RegExp(`^${camera.vendor}\\s+`, 'i'), ''))
    for (const key of [full, withoutVendor]) {
      if (key && key.length > bestLen && header.includes(key)) {
        best = camera
        bestLen = key.length
      }
    }
  }
  return best ?? matchModelToken(cameras, instrume)
}

/** The first word of a model name that carries a digit — "asi2600mc" in
 *  "ZWO ASI2600MC Pro". Short ones ("6d") are too generic to match on. */
function modelToken(model: string): string | null {
  const word = model.toLowerCase().split(/[^a-z0-9]+/).find((w) => /\d/.test(w))
  return word && word.length >= 4 ? word : null
}

/** Fallback for variants the catalog doesn't list ("ASI2600MC Duo",
 *  "ASI1600MM Cool"): a camera whose model token appears as a whole word in
 *  the header. Several catalog entries can share a token ("ASI585MC" and
 *  "ASI585MC Pro", same sensor); the shortest name is the base model. When
 *  they disagree on mono/colour ("Atik 460EX Color" / "Mono") any pick would
 *  be a guess, so there is no match. */
function matchModelToken(cameras: Camera[], instrume: string): Camera | null {
  const words = new Set(instrume.toLowerCase().split(/[^a-z0-9]+/))
  const candidates = cameras.filter((c) => {
    const token = modelToken(c.model)
    return token !== null && words.has(token)
  })
  if (candidates.length === 0 || candidates.some((c) => c.mono !== candidates[0].mono)) return null
  return candidates.reduce((a, b) => (b.model.length < a.model.length ? b : a))
}

/** The mode closest to the given gain; with no gain, the one with the
 *  lowest read noise. */
export function nearestMode(camera: Camera, gain: number | null | undefined): CameraMode {
  if (gain === null || gain === undefined || !Number.isFinite(gain)) {
    return camera.modes.reduce((best, m) => (m.readNoise < best.readNoise ? m : best))
  }
  return camera.modes.reduce((best, m) => (Math.abs(m.gain - gain) < Math.abs(best.gain - gain) ? m : best))
}

/** Matches a model or sensor name against the query's words, in any order.
 *  An empty query returns every camera, unlimited — `limit` only bounds an
 *  actual search, where a long result list is the case worth capping. */
export function searchCameras(cameras: Camera[], query: string, limit = 50): Camera[] {
  const words = query.toLowerCase().trim().split(/\s+/).filter(Boolean)
  if (words.length === 0) return cameras
  const matches = cameras.filter((c) => {
    const haystack = `${c.model} ${c.sensor} ${c.vendor}`.toLowerCase()
    return words.every((w) => haystack.includes(w))
  })
  return matches.slice(0, limit)
}

let cachedCatalog: Promise<Camera[]> | null = null

/** Fetches and memoises the bundled catalog. */
export function loadCameraCatalog(): Promise<Camera[]> {
  if (!cachedCatalog) {
    cachedCatalog = fetch('/catalogs/cameras.json')
      .then((res) => res.json())
      .then(parseCatalog)
      .catch((err) => {
        cachedCatalog = null
        throw err
      })
  }
  return cachedCatalog
}
